    "harper.linters.SemicolonApostrophe": {
      "type": "boolean",
      "default": true,
      "description": "Corrects semicolons accidentally typed instead of apostrophes."
    },
    "harper.linters.SentenceCapitalization": {
      "type": "boolean",
      "default": true,
      "description": "The opening word of a sentence should almost always be capitalized."
    },
    "harper.linters.ShootOneselfInTheFoot": {
      "type": "boolean",
      "default": true,
      "description": "Corrects non-standard variants of \u0027shoot oneself in the foot\u0027."
    },
    "harper.linters.SimpleGrammatical": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `simply grammatical` to `simple grammatical` for proper adjective usage."
    },
    "harper.linters.SimplePastToPastParticiple": {
      "type": "boolean",
      "default": true,
      "description": "Corrects simple past tense verbs to past participle after auxiliary verbs like \"have\" or \"be\"."
    },
    "harper.linters.SinceDuration": {
      "type": "boolean",
      "default": true,
      "description": "Detects the use of \u0027since\u0027 with a duration instead of a point in time."
    },
    "harper.linters.SingleBe": {
      "type": "boolean",
      "default": true,
      "description": "Removes adjacent duplicate inflections of `be`, including contracted forms followed by another `be` verb."
    },
    "harper.linters.SneakingSuspicion": {
      "type": "boolean",
      "default": true,
      "description": "Changes `sneaky suspicion` to `sneaking suspicion`."
    },
    "harper.linters.SomeOfThe": {
      "type": "boolean",
      "default": true,
      "description": "Quantity words such as `some` normally take `of` before a definite article. Including `of` signals that you mean a subset of a larger set, preventing a momentary stumble in comprehension."
    },
    "harper.linters.SomeWithoutArticle": {
      "type": "boolean",
      "default": true,
      "description": "Detects the redundant article in front of `some` and suggests more natural phrasing."
    },
    "harper.linters.Somebody": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `somebody`."
    },
    "harper.linters.SomebodyElses": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `somebody else\u0027s` when the `\u0027s` is in the wrong place."
    },
    "harper.linters.Somehow": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `somehow`."
    },
    "harper.linters.Someone": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `someone`."
    },
    "harper.linters.SomethingIs": {
      "type": "boolean",
      "default": true,
      "description": "Flags forms like `somethings` before progressive verbs and suggests using `something\u0027s` or `something is`."
    },
    "harper.linters.SomewhatSomething": {
      "type": "boolean",
      "default": true,
      "description": "Flags the phrase `somewhat of a` in favor of `something of a`, which can be considered more traditional."
    },
    "harper.linters.Somewhere": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `somewhere`."
    },
    "harper.linters.SoonerOrLater": {
      "type": "boolean",
      "default": true,
      "description": "Fixes the improper phrase `sooner than later` by suggesting standard alternatives."
    },
    "harper.linters.SoughtAfter": {
      "type": "boolean",
      "default": true,
      "description": "Correct `sort after` to `sought after`"
    },
    "harper.linters.Spaces": {
      "type": "boolean",
      "default": true,
      "description": "Words should be separated by at most one space."
    },
    "harper.linters.SpecialAttention": {
      "type": "boolean",
      "default": true,
      "description": "Changes `spacial attention` to `special attention`."
    },
    "harper.linters.SpellCheck": {
      "type": "boolean",
      "default": true,
      "description": "Looks and provides corrections for misspelled words."
    },
    "harper.linters.SpelledNumbers": {
      "type": "boolean",
      "default": false,
      "description": "Most style guides recommend that you spell out numbers less than ten."
    },
    "harper.linters.SplitWords": {
      "type": "boolean",
      "default": true,
      "description": "Finds missing spaces in improper compound words."
    },
    "harper.linters.Starving": {
      "type": "boolean",
      "default": true,
      "description": "Encourages vivid writing by suggesting `starving` instead of weaker expressions like `very hungry.`"
    },
    "harper.linters.StateOfTheArt": {
      "type": "boolean",
      "default": true,
      "description": "Detects incorrect usage of `state of art` and suggests `state of the art` as the correct phrase."
    },
    "harper.linters.StatuteOfLimitations": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `statue of limitations` to `statute of limitations`."
    },
    "harper.linters.SubjectPronoun": {
      "type": "boolean",
      "default": true,
      "description": "Fixes sentences that start with `me and X` by putting the proper noun first and using `I`."
    },
    "harper.linters.SufficeItToSay": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `suffice to say` to `suffice it to say`."
    },
    "harper.linters.SupposedTo": {
      "type": "boolean",
      "default": true,
      "description": "Fixes `suppose to` to the correct `supposed to`."
    },
    "harper.linters.TakeItPersonally": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `take it personal` to `take it personally`."
    },
    "harper.linters.TalkToYouLater": {
      "type": "boolean",
      "default": true,
      "description": "Expands an initialism."
    },
    "harper.linters.ThanksALot": {
      "type": "boolean",
      "default": true,
      "description": "Corrects the missing article in `thanks lot`, forming `thanks a lot`."
    },
    "harper.linters.ThatChallenged": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `the challenged` to `that challenged` for proper relative clause usage."
    },
    "harper.linters.ThatThan": {
      "type": "boolean",
      "default": true,
      "description": "Corrects the typo `that` to `than` in comparisons."
    },
    "harper.linters.ThatThis": {
      "type": "boolean",
      "default": true,
      "description": "Fixes `the this` to the correct phrase `that this`."
    },
    "harper.linters.ThatWhich": {
      "type": "boolean",
      "default": true,
      "description": "Repeating the word \"that\" is often redundant. The phrase `that which` is easier to read."
    },
    "harper.linters.The": {
      "type": "boolean",
      "default": true,
      "description": "Fixes especially common misspellings of the word `the`"
    },
    "harper.linters.TheAnother": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `the another`."
    },
    "harper.linters.TheHowWhy": {
      "type": "boolean",
      "default": true,
      "description": "Removes the extra `the` from expressions like `the how`, skipping `how to` and `who\u0027s who`."
    },
    "harper.linters.TheMy": {
      "type": "boolean",
      "default": true,
      "description": "Flags the definite article used together with a possessive."
    },
    "harper.linters.ThenThan": {
      "type": "boolean",
      "default": true,
      "description": "Corrects mixing up `then` and `than`."
    },
    "harper.linters.Therefore": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `therefore`."
    },
    "harper.linters.Theres": {
      "type": "boolean",
      "default": true,
      "description": "Replaces the mistaken possessive `their\u0027s` before a determiner with the contraction `there\u0027s`."
    },
    "harper.linters.Thereupon": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `thereupon`."
    },
    "harper.linters.ThesesThese": {
      "type": "boolean",
      "default": true,
      "description": "Corrects the common misspelling of `these` as `theses`."
    },
    "harper.linters.ThingThink": {
      "type": "boolean",
      "default": true,
      "description": "Corrects the typo `thing` when it should be `think`."
    },
    "harper.linters.ThoughThought": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `though` when it\u0027s a typo for `thought`."
    },
    "harper.linters.ThoughtProcess": {
      "type": "boolean",
      "default": true,
      "description": "Changes `though process` to `thought process`."
    },
    "harper.linters.ThrowAway": {
      "type": "boolean",
      "default": true,
      "description": "Finds the typo `through away` and suggests `throw away` or `threw away` instead."
    },
    "harper.linters.ThrowRubbish": {
      "type": "boolean",
      "default": true,
      "description": "Checks for throwing rubbish rather than throwing it away."
    },
    "harper.linters.TickingTimeClock": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `ticking time clock` to `ticking time bomb` for idiomatic urgency or `ticking clock` otherwise."
    },
    "harper.linters.ToAdverb": {
      "type": "boolean",
      "default": true,
      "description": "Flags duplicated `to` around certain adverbs (e.g. `to never to`) and offers fixes that keep only one `to`."
    },
    "harper.linters.ToBeHonest": {
      "type": "boolean",
      "default": true,
      "description": "Expands an initialism."
    },
    "harper.linters.ToDoHyphen": {
      "type": "boolean",
      "default": true,
      "description": "Ensures `to-do` is correctly hyphenated."
    },
    "harper.linters.ToGreatLengths": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `through great lengths` to `to great lengths`."
    },
    "harper.linters.ToTheMannerBorn": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `to the manor born` to `to the manner born`, ensuring the intended meaning of being naturally suited to a way of life."
    },
    "harper.linters.ToTooIdioms": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `to` used instead of `too`."
    },
    "harper.linters.ToTwoToo": {
      "type": "boolean",
      "default": true,
      "description": "Corrects homophone confusion between `to` and `too`."
    },
    "harper.linters.ToWorryAbout": {
      "type": "boolean",
      "default": true,
      "description": "Fixes incorrect use of `to worried about`."
    },
    "harper.linters.TongueInCheek": {
      "type": "boolean",
      "default": true,
      "description": "Corrects the idiom when `and` replaces the needed preposition."
    },
    "harper.linters.TooTo": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `too` used instead of `to`."
    },
    "harper.linters.Touristic": {
      "type": "boolean",
      "default": true,
      "description": "Suggests replacing the uncommon word `touristic` with `tourist`, `tourism`, and/or `touristy`."
    },
    "harper.linters.Towards": {
      "type": "boolean",
      "default": true,
      "description": "Removes redundant `to` before `towards`."
    },
    "harper.linters.TrialAndError": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `trail` to `trial` in `trial and error`."
    },
    "harper.linters.TumblrNames": {
      "type": "boolean",
      "default": true,
      "description": "Ensure proper capitalization of Tumblr-related terms."
    },
    "harper.linters.TurnItOff": {
      "type": "boolean",
      "default": true,
      "description": "Fixes the mistake in the phrase `turn it off`."
    },
    "harper.linters.USUniversities": {
      "type": "boolean",
      "default": true,
      "description": "Ensure proper capitalization of major universities in the United States."
    },
    "harper.linters.UnclosedQuotes": {
      "type": "boolean",
      "default": true,
      "description": "Quotation marks should always be closed. Unpaired quotation marks are a hallmark of sloppy work."
    },
    "harper.linters.Underclock": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `underclock`."
    },
    "harper.linters.UnitedOrganizations": {
      "type": "boolean",
      "default": true,
      "description": "When referring to national or international organizations, make sure to treat them as a proper noun."
    },
    "harper.linters.Unless": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `unless if`."
    },
    "harper.linters.UpdatePlaceNames": {
      "type": "boolean",
      "default": true,
      "description": "This rule looks for deprecated place names and offers to update them."
    },
    "harper.linters.Upset": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `upset`."
    },
    "harper.linters.Upward": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `upward`."
    },
    "harper.linters.UseGenitive": {
      "type": "boolean",
      "default": false,
      "description": "Looks for situations where the genitive case of \"there\" should be used."
    },
    "harper.linters.VerbToAdjective": {
      "type": "boolean",
      "default": true,
      "description": "Looks for situations where a verb was written where an adjective is often intended."
    },
    "harper.linters.VeryUnique": {
      "type": "boolean",
      "default": true,
      "description": "Flags phrases like `very unique`, `pretty unique`, etc., and suggests using `unique` alone or a more precise adjective such as `special`, `rare`, or `unusual`."
    },
    "harper.linters.ViceVersa": {
      "type": "boolean",
      "default": true,
      "description": "Recommends writing ‘vice versa’ without hyphens."
    },
    "harper.linters.WantBe": {
      "type": "boolean",
      "default": true,
      "description": "Detects incorrect usage of `want be` and suggests `won\u0027t be` or `want to be` based on context."
    },
    "harper.linters.WasAloud": {
      "type": "boolean",
      "default": true,
      "description": "Ensures `was aloud` and `were aloud` are corrected to `was allowed` or `were allowed` when referring to permission."
    },
    "harper.linters.WaveFunction": {
      "type": "boolean",
      "default": true,
      "description": "Identifies the mistake of merging `wave` and `function` into one word. In quantum mechanics, a `wave function` (written as two words) describes the mathematical function that represents the quantum state of a particle or system. Correct usage is crucial for clear and accurate scientific communication."
    },
    "harper.linters.WayTooAdjective": {
      "type": "boolean",
      "default": true,
      "description": "Replaces the preposition `to` with the adverb `too` after `way` when followed by an adjective (e.g. `way too fast`)"
    },
    "harper.linters.WellBeing": {
      "type": "boolean",
      "default": true,
      "description": "Ensures `well-being` is correctly hyphenated."
    },
    "harper.linters.WellEducated": {
      "type": "boolean",
      "default": true,
      "description": "Replaces `good-educated` with the accepted compound `well-educated`."
    },
    "harper.linters.WellKept": {
      "type": "boolean",
      "default": true,
      "description": "Flags `highly-kept` and recommends `well-kept` as an alternative."
    },
    "harper.linters.Whereas": {
      "type": "boolean",
      "default": true,
      "description": "The Whereas rule is designed to identify instances where the phrase `where as` is used in text and suggests replacing it with the single word `whereas`."
    },
    "harper.linters.Whereupon": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `whereupon`."
    },
    "harper.linters.WhetYourAppetite": {
      "type": "boolean",
      "default": true,
      "description": "Ensures `whet your appetite` is used correctly, distinguishing it from the incorrect `wet` variation."
    },
    "harper.linters.WholeEntire": {
      "type": "boolean",
      "default": true,
      "description": "Corrects the redundancy in `whole entire` to `whole` or `entire`."
    },
    "harper.linters.WidelyAccepted": {
      "type": "boolean",
      "default": true,
      "description": "Flags `wide accepted`, `wide acceptable`, or `wide used` and recommends switching `wide` to the adverb `widely`."
    },
    "harper.linters.Widespread": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `widespread`."
    },
    "harper.linters.WillContain": {
      "type": "boolean",
      "default": true,
      "description": "Incorrect verb form: `will` should be followed by the base form `contain`."
    },
    "harper.linters.WinPrize": {
      "type": "boolean",
      "default": true,
      "description": "Catches the mix-up between `price`/`prise` and `prize` after the verb `win`."
    },
    "harper.linters.WishCould": {
      "type": "boolean",
      "default": true,
      "description": "Checks for `can` being used after `wish` when it should be `could`."
    },
    "harper.linters.WordPressDotcom": {
      "type": "boolean",
      "default": true,
      "description": "Ensures correct capitalization of WordPress.com. This rule verifies that the official stylization of WordPress.com is used when referring to the hosting provider."
    },
    "harper.linters.Worldwide": {
      "type": "boolean",
      "default": true,
      "description": "Looks for incorrect spacing inside the closed compound `worldwide`."
    },
    "harper.linters.WorseOrWorst": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `worse` and `worst` used in contexts where the other belongs."
    },
    "harper.linters.WorstCaseScenario": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `worst-case scenario` when the hyphen is missing or `worse` is used instead of `worst`."
    },
    "harper.linters.WouldNeverHave": {
      "type": "boolean",
      "default": true,
      "description": "Corrects `would/could have never` to `never would/could have`."
    },
    "harper.linters.WroughtIron": {
      "type": "boolean",
      "default": true,
      "description": "`Wrought iron` is low-carbon, malleable iron used for decorative work; variants like `rod iron` or `rot iron` are phonetic misspellings that may confuse readers."
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "LSP4IJ/ruby-lsp/settings.schema.json",
  "title": "LSP4IJ Ruby language server settings JSON schema",
  "description": "JSON schema for Ruby language server settings.",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "swift.path": {
      "type": "string",
      "default": "",
      "description": "Override the default path of the folder containing the Swift executables. The default is to look in the `PATH` environment variable. This path is also used to search for other executables used by the extension like `sourcekit-lsp` and `lldb`."
    },
    "swift.buildArguments": {
      "type": "array",
      "default": [],
      "items": {
        "type": "string"
      },
      "description": "Additional arguments to pass to `swift build` and `swift test`. Keys and values should be provided as individual entries in the list. If you have created a copy of the build task in `tasks.json` then these build arguments will not be propagated to that task."
    },
    "swift.scriptSwiftLanguageVersion": {
      "type": "string",
      "enum": [
        "6",
        "5",
        "4.2",
        "4",
        "Ask Every Run"
      ],
      "enumDescriptions": [
        "Use Swift 6 when running Swift scripts.",
        "Use Swift 5 when running Swift scripts.",
        "Prompt to select the Swift version each time a script is run."
      ],
      "default": "6",
      "description": "The default Swift version to use when running Swift scripts."
    },
    "swift.packageArguments": {
      "type": "array",
      "default": [],
      "items": {
        "type": "string"
      },
      "description": "Additional arguments to pass to swift commands that do package resolution, such as `swift package resolve`, `swift package update`, `swift build` and `swift test`. Keys and values should be provided as individual entries in the list."
    },
    "swift.additionalTestArguments": {
      "type": "array",
      "default": [],
      "items": {
        "type": "string"
      },
      "description": "Additional arguments to pass to the `swift test` or `swift build` commands used when building and running tests from within VS Code."
    },
    "swift.testEnvironmentVariables": {
      "type": "object",
      "patternProperties": {
        ".*": {
          "type": "string"
        }
      },
      "default": {},
      "description": "Environment variables to set when running tests. To set environment variables when debugging an application you should edit the `env` field in the relevant `launch.json` configuration."
    },
    "swift.sanitizer": {
      "type": "string",
      "default": "off",
      "enum": [
        "off",
        "thread",
        "address"
      ],
      "description": "Runtime [sanitizer instrumentation](https://www.swift.org/documentation/server/guides/llvm-sanitizers.html)."
    },
    "swift.searchSubfoldersForPackages": {
      "type": "boolean",
      "default": false,
      "description": "Search sub-folders of workspace folder for Swift Packages at start up."
    },
    "swift.autoGenerateLaunchConfigurations": {
      "type": "boolean",
      "default": true,
      "description": "When loading a `Package.swift`, auto-generate `launch.json` configurations for running any executables."
    },
    "swift.disableAutoResolve": {
      "type": "boolean",
      "default": false,
      "description": "Disable automatic running of `swift package resolve` whenever the `Package.swift` or `Package.resolve` files are updated. This will also disable searching for command plugins and the initial test discovery process."
    },
    "swift.diagnosticsCollection": {
      "type": "string",
      "default": "keepSourceKit",
      "enum": [
        "onlySwiftc",
        "onlySourceKit",
        "keepSwiftc",
        "keepSourceKit",
        "keepAll"
      ],
      "enumDescriptions": [
        "Only provide diagnostics from `swiftc`.",
        "Only provide diagnostics from `SourceKit`.",
        "When merging diagnostics, give precedence to diagnostics from `swiftc`.",
        "When merging diagnostics, give precedence to diagnostics from `SourceKit`.",
        "Keep diagnostics from all providers."
      ],
      "description": "Controls how diagnostics from the various providers are merged into the collection of `swift` errors and warnings shown in the Problems pane."
    },
    "swift.diagnosticsStyle": {
      "type": "string",
      "default": "llvm",
      "enum": [
        "default",
        "llvm",
        "swift"
      ],
      "markdownEnumDescriptions": [
        "Use whichever diagnostics style `swiftc` produces by default.",
        "Use the `llvm` diagnostic style. This allows the parsing of \"notes\".",
        "Use the `swift` diagnostic style. This means that \"notes\" will not be parsed. This option has no effect in Swift versions prior to 5.10."
      ],
      "description": "The formatting style used when printing diagnostics in the Problems panel. Corresponds to the `-diagnostic-style` option to pass to `swiftc` when running `swift` tasks."
    },
    "swift.backgroundCompilation": {
      "type": "boolean",
      "default": false,
      "description": "**Experimental**: Run `swift build` in the background whenever a file is saved. It is possible the background compilation will already be running when you attempt a compile yourself, so this is disabled by default."
    },
    "swift.actionAfterBuildError": {
      "type": "string",
      "default": "Focus Terminal",
      "enum": [
        "Focus Problems",
        "Focus Terminal",
        "Do Nothing"
      ],
      "enumDescriptions": [
        "Focus on Problems View",
        "Focus on Build Task Terminal"
      ],
      "description": "Action after a Build task generates errors."
    },
    "swift.buildPath": {
      "type": "string",
      "default": "",
      "description": "The path to a directory that will be used for build artifacts. This path will be added to all swift package manager commands that are executed by vscode-swift extension via `--scratch-path` option. When no value provided - nothing gets passed to swift package manager and it will use its default value of `.build` folder in the workspace.\n\nYou can use absolute path for directory or the relative path, which will use the workspace path as a base. Note that VS Code does not respect tildes (`~`) in paths which represents user home folder under *nix systems."
    },
    "swift.disableSwiftPackageManagerIntegration": {
      "type": "boolean",
      "default": false,
      "description": "Disables automated Build Tasks, Package Dependency view, Launch configuration generation and TestExplorer."
    },
    "swift.warnAboutSymlinkCreation": {
      "type": "boolean",
      "default": true,
      "description": "Controls whether or not the extension will warn about being unable to create symlinks. (Windows only)"
    },
    "swift.enableTerminalEnvironment": {
      "type": "boolean",
      "default": true,
      "description": "Controls whether or not the extension will contribute environment variables defined in `Swift: Environment Variables` to the integrated terminal. If this is set to `true` and a custom `Swift: Path` is also set then the swift path is appended to the terminal\u0027s `PATH`."
    },
    "swift.pluginArguments": {
      "default": [],
      "oneOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "object",
          "patternProperties": {
            "^([a-zA-Z0-9_-]+(:[a-zA-Z0-9_-]+)?)$": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          }
        }
      ],
      "description": "Configure a list of arguments to pass to command invocations. This can either be an array of arguments, which will apply to all command invocations, or an object with command names as the key where the value is an array of arguments."
    },
    "swift.pluginPermissions": {
      "type": "object",
      "default": {},
      "patternProperties": {
        "^([a-zA-Z0-9_-]+(:[a-zA-Z0-9_-]+)?)$": {
          "type": "object",
          "properties": {
            "disableSandbox": {
              "type": "boolean",
              "description": "Disable using the sandbox when executing plugins"
            },
            "allowWritingToPackageDirectory": {
              "type": "boolean",
              "description": "Allow the plugin to write to the package directory"
            },
            "allowWritingToDirectory": {
              "oneOf": [
                {
                  "type": "string",
                  "description": "Allow the plugin to write to an additional directory"
                },
                {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "Allow the plugin to write to additional directories"
                }
              ]
            },
            "allowNetworkConnections": {
              "type": "string",
              "description": "Allow the plugin to make network connections"
            }
          }
        }
      },
      "description": "Configures a list of permissions to be used when running a command plugins.\n\nPermissions objects are defined in the form:\n\n`{ \"PluginName:command\": { \"allowWritingToPackageDirectory\": true } }`.\n\nA key of `PluginName:command` will set permissions for a specific command. A key of `PluginName` will set permissions for all commands in the plugin."
    },
    "swift.attachmentsPath": {
      "type": "string",
      "default": ".build/attachments",
      "description": "The path to a directory that will be used to store attachments produced during a test run.\n\nA relative path resolves relative to the root directory of the workspace running the test(s)"
    },
    "swift.excludeFromCodeCoverage": {
      "description": "A list of paths to exclude from code coverage reports. Paths can be absolute or relative to the workspace root.",
      "type": "array",
      "items": {
        "type": "string"
      },
      "default": []
    },
    "swift.excludePathsFromPackageDependencies": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "default": [
        ".git",
        ".github"
      ],
      "description": "A list of paths to exclude from the Package Dependencies view."
    },
    "swift.showBuildStatus": {
      "type": "string",
      "default": "swiftStatus",
      "enum": [
        "never",
        "swiftStatus",
        "progress",
        "notification"
      ],
      "enumDescriptions": [
        "Never show the Swift build status.",
        "Show the Swift build status in a status bar item provided by the Swift extension.",
        "Show the Swift build status in the \"Progress Message\" status bar item provided by VS Code.",
        "Show the Swift build status as a progress notification."
      ],
      "description": "Controls where to show the Swift build progress when running a `swift` build task."
    },
    "swift.showCreateSwiftProjectInWelcomePage": {
      "type": "boolean",
      "default": true,
      "description": "Controls whether or not the create new swift project button appears in the welcome page."
    },
    "swift.openAfterCreateNewProject": {
      "type": "string",
      "enum": [
        "always",
        "alwaysNewWindow",
        "whenNoFolderOpen",
        "prompt"
      ],
      "enumDescriptions": [
        "Always open in current window.",
        "Always open in a new window.",
        "Only open in current window when no folder is opened.",
        "Always prompt for action."
      ],
      "default": "prompt",
      "description": "Controls whether to open a swift project automatically after creating it."
    },
    "swift.sourcekit-lsp.serverPath": {
      "type": "string",
      "markdownDeprecationMessage": "**Deprecated**: The sourcekit-lsp executable relies on outputs from tools in your current toolchain. If your sourcekit-lsp version does not match your toolchain you may experience unexpected behaviour. Only modify this setting when developing sourcekit-lsp.",
      "order": 1,
      "description": "The path of the `sourcekit-lsp` executable. The default is to look in the path where `swift` is found."
    },
    "swift.sourcekit-lsp.serverArguments": {
      "type": "array",
      "default": [],
      "items": {
        "type": "string"
      },
      "order": 2,
      "description": "Arguments to pass to SourceKit-LSP. Keys and values should be provided as individual entries in the list. e.g. `[\u0027--log-level\u0027, \u0027debug\u0027]`"
    },
    "swift.sourcekit-lsp.supported-languages": {
      "type": "array",
      "default": [
        "swift",
        "objective-c",
        "objective-cpp",
        "c",
        "cpp"
      ],
      "items": {
        "type": "string",
        "enum": [
          "swift",
          "objective-c",
          "objective-cpp",
          "c",
          "cpp"
        ]
      },
      "order": 3,
      "description": "List of languages supported by SourceKit-LSP. This is used to determine whether SourceKit-LSP should provide language features for a particular file type. If you want a different extension to provide support for a language, remove it from the list."
    },
    "swift.sourcekit-lsp.backgroundIndexing": {
      "type": "string",
      "enum": [
        "on",
        "off",
        "auto"
      ],
      "default": "auto",
      "order": 4,
      "description": "Turns background indexing `on` or `off`. `auto` will enable background indexing if the Swift version is \u003e\u003d 6.1. This option has no effect in Swift versions prior to 6.0."
    },
    "swift.sourcekit-lsp.trace.server": {
      "type": "string",
      "default": "off",
      "enum": [
        "off",
        "messages",
        "verbose"
      ],
      "order": 5,
      "description": "Controls logging the communication between VS Code and the SourceKit-LSP language server. Logs can be viewed in Output \u003e SourceKit Language Server."
    },
    "swift.sourcekit-lsp.disable": {
      "type": "boolean",
      "default": false,
      "order": 6,
      "description": "Disable SourceKit-LSP. This will turn off features like code completion, error diagnostics and jump-to-definition. Features like swift-testing test discovery will not work correctly."
    },
    "sourcekit-lsp.inlayHints.enabled": {
      "type": "boolean",
      "default": true,
      "markdownDeprecationMessage": "**Deprecated**: Please use `#editor.inlayHints.enabled#` instead.",
      "description": "Display Inlay Hints. Inlay Hints are variable annotations indicating their inferred type. They are only available if you are using Swift 5.6 or later."
    },
    "sourcekit-lsp.support-c-cpp": {
      "type": "string",
      "default": "cpptools-inactive",
      "enum": [
        "enable",
        "disable",
        "cpptools-inactive"
      ],
      "enumDescriptions": [
        "Always enable",
        "Always disable",
        "Disable when C/C++ extension is active"
      ],
      "markdownDeprecationMessage": "**Deprecated**: Please use `#swift.sourcekit-lsp.supported-languages#` instead.",
      "description": "Add LSP functionality for C/C++ files. By default this is set to disable when the C/C++ extension is active."
    },
    "sourcekit-lsp.serverPath": {
      "type": "string",
      "markdownDeprecationMessage": "**Deprecated**: Please use `#swift.sourcekit-lsp.serverPath#` instead.",
      "description": "The path of the `sourcekit-lsp` executable. The default is to look in the path where `swift` is found."
    },
    "sourcekit-lsp.serverArguments": {
      "type": "array",
      "default": [],
      "items": {
        "type": "string"
      },
      "markdownDeprecationMessage": "**Deprecated**: Please use `#swift.sourcekit-lsp.serverArguments#` instead.",
      "description": "Arguments to pass to SourceKit-LSP. Keys and values should be provided as individual entries in the list. e.g. `[\u0027--log-level\u0027, \u0027debug\u0027]`"
    },
    "sourcekit-lsp.trace.server": {
      "type": "string",
      "default": "off",
      "enum": [
        "off",
        "messages",
        "verbose"
      ],
      "markdownDeprecationMessage": "**Deprecated**: Please use `#swift.sourcekit-lsp.trace.server#` instead.",
      "description": "Traces the communication between VS Code and the SourceKit-LSP language server."
    },
    "sourcekit-lsp.disable": {
      "type": "boolean",
      "default": false,
      "markdownDeprecationMessage": "**Deprecated**: Please use `#swift.sourcekit-lsp.disable#` instead.",
      "description": "Disable the running of SourceKit-LSP."
    },
    "swift.debugger.debugAdapter": {
      "type": "string",
      "default": "auto",
      "enum": [
        "auto",
        "lldb-dap",
        "CodeLLDB"
      ],
      "enumDescriptions": [
        "Automatically select which debug adapter to use based on your Swift toolchain version.",
        "Use the `lldb-dap` executable from the toolchain. Requires Swift 6 or later.",
        "Use the CodeLLDB extension\u0027s debug adapter."
      ],
      "order": 1,
      "description": "Select which debug adapter to use to debus Swift executables."
    },
    "swift.debugger.path": {
      "type": "string",
      "default": "",
      "order": 2,
      "description": "Path to lldb debug adapter."
    },
    "swift.debugger.setupCodeLLDB": {
      "type": "string",
      "default": "prompt",
      "enum": [
        "prompt",
        "alwaysUpdateGlobal",
        "alwaysUpdateWorkspace",
        "never"
      ],
      "enumDescriptions": [
        "Prompt to update CodeLLDB settings when they are incorrect.",
        "Always automatically update CodeLLDB settings globally when they are incorrect.",
        "Always automatically update CodeLLDB settings in the workspace when they are incorrect.",
        "Never automatically update CodeLLDB settings when they are incorrect."
      ],
      "order": 3,
      "description": "Choose how CodeLLDB settings are updated when debugging Swift executables."
    },
    "swift.debugger.useDebugAdapterFromToolchain": {
      "type": "boolean",
      "default": false,
      "markdownDeprecationMessage": "**Deprecated**: Use the `swift.debugger.debugAdapter` setting instead. This will be removed in future versions of the Swift extension.",
      "order": 4,
      "description": "Use the LLDB debug adapter packaged with the Swift toolchain as your debug adapter. Note: this is only available starting with Swift 6. The CodeLLDB extension will be used if your Swift toolchain does not contain lldb-dap."
    },
    "swift.swiftEnvironmentVariables": {
      "type": "object",
      "patternProperties": {
        ".*": {
          "type": "string"
        }
      },
      "default": {},
      "order": 1,
      "description": "Additional environment variables to pass to swift operations (`swift build`, `swift resolve`, etc...)."
    },
    "swift.runtimePath": {
      "type": "string",
      "default": "",
      "order": 2,
      "description": "The path of the folder containing the Swift runtime libraries. This is of use when supporting non-standard SDK layouts on Windows. On Windows the runtime path is added to the `Path` environment variable. This is of less use on macOS and Linux but will be added to `DYLD_LIBRARY_PATH` and `LD_LIBRARY_PATH` environment variables respectively on each platform. "
    },
    "swift.SDK": {
      "type": "string",
      "default": "",
      "order": 3,
      "description": "The path of the SDK to compile against (`--sdk` parameter). This is of use when supporting non-standard SDK layouts on Windows and using custom SDKs. The default SDK is determined by the environment on macOS and Windows.\n\nFor SwiftPM projects, prefer using `swift.swiftSDK` with a triple (such as `arm64-apple-ios`) or Swift SDK name instead."
    },
    "swift.swiftSDK": {
      "type": "string",
      "default": "",
      "description": "The [Swift SDK](https://github.com/swiftlang/swift-evolution/blob/main/proposals/0387-cross-compilation-destinations.md) to compile against (`--swift-sdk` parameter)."
    },
    "swift.disableSandox": {
      "type": "boolean",
      "default": false,
      "order": 4,
      "description": "Disable sandboxing when running SwiftPM commands. In most cases you should keep the sandbox enabled and leave this setting set to `false`"
    },
    "swift.diagnostics": {
      "type": "boolean",
      "default": false,
      "order": 100,
      "description": "Output additional diagnostics to the Swift Output View."
    }
  }
}
